 68	+}
 69	+
 70	+function exportFile() {
 71	+  if (todos.length === 0) {
 72	+    showMessage('Chưa có việc nào để sao lưu');
 73	+    return;
 74	+  }
 75	+  const data = { version: 1, todos: todos.map((t) => Object.fromEntries(FIELDS.map((f) => [f, t[f]]))) };
 76	+  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
 77	+  const url = URL.createObjectURL(blob);
 78	+  const a = document.createElement('a');
 79	+  a.href = url;
 80	+  a.download = `todo-sao-luu-${today()}.json`;
 81	+  a.click();
 82	+  setTimeout(() => URL.revokeObjectURL(url), 0);
