 84	+    showMessage('File sao lưu đã lưu, nhưng quá lớn nên app không nhập lại được.', true);
 85	+  } else {
 86	+    showMessage(`Đã sao lưu ${todos.length} việc.`);
 87	+  }
 88	+}
 89	+
 90	+// --- Import from file (F2, F5 step 6) ---
 91	+
 92	+const isPlainObject = (v) => typeof v === 'object' && v !== null && !Array.isArray(v);
 93	+const hasExactKeys = (obj, keys) => Object.keys(obj).length === keys.length && keys.every((k) => Object.hasOwn(obj, k));
 94	+
 95	+// Returns the list of todos, or a reason string. Content is only parsed as data, never run.
 96	+function parseBackup(text) {
 97	+  let data;
 98	+  try {
 99	+    data = JSON.parse(text);
100	+  } catch {
101	+    return 'not-backup';
102	+  }
103	+  if (!isPlainObject(data) || !hasExactKeys(data, ['version', 'todos']) || data.version !== 1 || !Array.isArray(data.todos)) {
104	+    return 'not-backup';
105	+  }
106	+  if (data.todos.length === 0) return 'empty';
107	+  const ids = new Set();
108	+  for (const t of data.todos) {
109	+    if (!isPlainObject(t) || !hasExactKeys(t, FIELDS)) return 'not-backup';
110	+    if (typeof t.id !== 'string' || typeof t.title !== 'string' || typeof t.done !== 'boolean') return 'not-backup';
111	+    if (typeof t.createdAt !== 'number' || !Number.isFinite(t.createdAt)) return 'damaged';
112	+    if (t.id === '' || ids.has(t.id) || t.title.trim() === '') return 'damaged';
113	+    ids.add(t.id);
114	+  }
115	+  return data.todos.map((t) => ({ id: t.id, title: t.title, done: t.done, createdAt: t.createdAt }));
116	+}
117	+
118	+const KEEP = 'Danh sách của bạn vẫn giữ nguyên.';
119	+const REJECTED = {
120	+  'too-big': `File này quá lớn (hơn 1 MB) nên không nhập được. ${KEEP} Hãy chọn một file sao lưu khác.`,
