123	+  'damaged': `File sao lưu này bị lỗi (có việc trùng nhau, thiếu tiêu đề hoặc sai ngày tạo) nên không nhập được. ${KEEP} Hãy chọn một file sao lưu khác.`,
124	+  'empty': `File sao lưu này không có việc nào nên không nhập. ${KEEP}`,
125	+};
126	+
127	+function confirmText(count) {
128	+  if (loadFailed && todos.length === 0) return `Thay danh sách đã lưu không đọc được bằng ${count} việc trong file?`;
129	+  if (loadFailed) return `Thay danh sách đã lưu không đọc được và ${todos.length} việc bạn vừa thêm (chưa lưu) bằng ${count} việc trong file?`;
130	+  if (todos.length > 0) return `Thay ${todos.length} việc hiện có bằng ${count} việc trong file?`;
131	+  return null; // empty list: nothing is lost, no confirmation (policy-security S2)
132	+}
133	+
134	+function askConfirm(text) {
135	+  const dialog = $('#confirm');
136	+  $('#confirm-text').textContent = text;
137	+  dialog.returnValue = '';
138	+  return new Promise((resolve) => {
139	+    dialog.addEventListener('close', () => resolve(dialog.returnValue === 'ok'), { once: true });
140	+    dialog.showModal();
141	+  });
142	+}
143	+
144	+async function importFile(file) {
145	+  if (file.size > MAX_IMPORT_BYTES) {
146	+    showMessage(REJECTED['too-big'], true);
147	+    return;
148	+  }
149	+  showMessage('Đang đọc file…');
150	+  let text;
151	+  try {
152	+    text = await file.text();
153	+  } catch {
154	+    showMessage(REJECTED.unreadable, true);
155	+    return;
156	+  }
157	+  const imported = parseBackup(text);
158	+  if (typeof imported === 'string') {
159	+    showMessage(REJECTED[imported], true);
160	+    return;
161	+  }
162	+  const question = confirmText(imported.length);
163	+  if (question && !(await askConfirm(question))) {
164	+    showMessage('');
165	+    return;
166	+  }
167	+  // The only write allowed while the saved list is unreadable. On failure the old list stays on screen and in memory.
168	+  if (!store.save(imported)) {
169	+    saveFailed = true;
170	+    showMessage(SAVE_FAILED, true);
171	+    return;
172	+  }
173	+  todos = imported;
174	+  loadFailed = false;
175	+  saveFailed = false;
176	+  showMessage(`Đã nhập ${imported.length} việc.`);
177	+  render();
178	 }
