242	 const store = {
243	+  // Returns { ok: true, todos } or { ok: false } when the saved list cannot be read.
244	+  // No key yet is a normal empty list. A value that does not parse, is not an array, or storage that throws is a read error:
245	+  // the caller must not overwrite it.
