252	-      return [];
253	+      return { ok: false };
254	     }
255	+    if (raw === null) return { ok: true, todos: [] };
256	+    let todos;
257	+    try {
258	+      todos = JSON.parse(raw);
259	+    } catch {
260	+      return { ok: false };
261	+    }
262	+    return Array.isArray(todos) ? { ok: true, todos } : { ok: false };
263	   },
