266	-    // localStorage is capped per origin (about 5 MB in most browsers). A failed write is only logged.
267	     try {
268	       localStorage.setItem(STORE_KEY, JSON.stringify(todos));
269	+      return true;
270	     } catch (err) {
271	       console.error('save failed', err);
272	+      return false;
273	     }
274	   },
275	 };
