     1	// Storage layer. Everything lives in this browser's localStorage: no server, no account, no sync.
     2	// Clearing site data, switching browser or switching device means starting from an empty list.
     3	const STORE_KEY = 'todo.v1';
     4	
     5	const store = {
     6	  // True when todo.v1 holds something that cannot be read as a list. Kept in page memory only. While it is true, save()
     7	  // never writes, so the unreadable data is not overwritten; only replace() (import, after the customer agreed) may.
     8	  readError: false,
     9	
    10	  // No key yet is an ordinary empty list. Unparsable data, data that is not an array, or storage that throws is a read error.
    11	  load() {
    12	    let todos = null;
    13	    try {
    14	      const raw = localStorage.getItem(STORE_KEY);
    15	      todos = raw === null ? [] : JSON.parse(raw);
    16	    } catch {
    17	      todos = null;
    18	    }
    19	    store.readError = !Array.isArray(todos);
    20	    return { todos: store.readError ? [] : todos, readError: store.readError };
    21	  },
    22	
    23	  // 'saved' | 'failed' (for example storage full, about 5 MB in most browsers) | 'skipped' (read error, nothing written).
    24	  save(todos) {
    25	    if (store.readError) return 'skipped';
    26	    return writeList(todos);
    27	  },
    28	
    29	  // The import path: writes even after a read error, and clears it only when the write succeeds.
    30	  replace(todos) {
    31	    const result = writeList(todos);
    32	    if (result === 'saved') store.readError = false;
    33	    return result;
    34	  },
    35	};
    36	
    37	function writeList(todos) {
    38	  try {
    39	    localStorage.setItem(STORE_KEY, JSON.stringify(todos));
    40	    return 'saved';
    41	  } catch {
    42	    return 'failed';
    43	  }
    44	}
